def list_gen_jobs(status=None, idempotency_key=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0012000" if __import__("os").path.isdir("./environment_mix/0012000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_gen_jobs"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(ok, error_obj=None, extra=None):
        # Prefer an existing log collection if present; else fall back to request_logs.json
        fname = None
        for candidate in ("api_requests.json", "request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, candidate)):
                fname = candidate
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": "ok" if ok else "error",
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_obj:
            row["error"] = error_obj
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    valid_status = {"queued", "running", "succeeded", "failed", "cancelled"}

    # Validate filters (but be tolerant: timestamps are best-effort parsed; invalid values are treated as "no filter")
    if status is not None:
        if not isinstance(status, str) or status not in valid_status:
            e = _err("VALIDATION_ERROR", "status must be one of queued,running,succeeded,failed,cancelled", field="status")
            _log(False, e["error"])
            return e

    if idempotency_key is not None:
        if not isinstance(idempotency_key, str):
            e = _err("VALIDATION_ERROR", "idempotency_key must be a string", field="idempotency_key")
            _log(False, e["error"])
            return e
        if not idempotency_key.strip():
            e = _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string", field="idempotency_key")
            _log(False, e["error"])
            return e

    if limit is None:
        limit_v = 20
    else:
        if not isinstance(limit, int) or not (1 <= limit <= 100):
            e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100", field="limit")
            _log(False, e["error"])
            return e
        limit_v = limit

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        e = _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided", field="cursor")
        _log(False, e["error"])
        return e

    def _parse_rfc3339_best_effort(val):
        # Accept RFC3339; if invalid, return None (tolerant for forward-compat + audit defect)
        if val is None:
            return None
        if not isinstance(val, str) or not val.strip():
            return None
        s = val.strip()
        # Accept 'Z'
        if s.endswith("Z"):
            s2 = s[:-1] + "+00:00"
        else:
            s2 = s
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt

    created_after_dt = _parse_rfc3339_best_effort(created_after)
    created_before_dt = _parse_rfc3339_best_effort(created_before)

    jobs = _load("gen_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    def _job_created_dt(job):
        ca = job.get("created_at")
        dt = _parse_rfc3339_best_effort(ca)
        return dt

    # Filter
    filtered = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if status is not None and j.get("status") != status:
            continue
        if idempotency_key is not None and j.get("idempotency_key") != idempotency_key:
            continue
        jdt = _job_created_dt(j)
        if created_after_dt is not None and jdt is not None and not (jdt > created_after_dt):
            continue
        if created_before_dt is not None and jdt is not None and not (jdt < created_before_dt):
            continue
        filtered.append(j)

    # Sort created_at desc (fallback to id desc for stability when timestamps missing/unparseable)
    def _sort_key(j):
        dt = _job_created_dt(j)
        # None sorts last
        ts = dt.timestamp() if isinstance(dt, datetime.datetime) else float("-inf")
        return (ts, j.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor as "start after the job with this id" in the sorted order (opaque to caller)
    start_idx = 0
    if cursor is not None:
        for i, j in enumerate(filtered):
            if j.get("id") == cursor:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit_v]
    has_more = (start_idx + limit_v) < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    resp = {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit_v,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        }
    }
    _log(True, extra={"result_count": len(page)})
    return resp

def get_gen_job(id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0012000" if __import__("os").path.isdir("./environment_mix/0012000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_gen_job"

    def _log(status_s, error=None, extra=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status_s,
                "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error:
                row["error"] = error
            if extra and isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    if not isinstance(id, str) or not id.strip():
        e = _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        _log("error", e["error"])
        return e

    jobs = _load("gen_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == id:
            job = j
            break

    if job is None:
        e = _err("NOT_FOUND", "Generation job not found", id=id)
        _log("error", e["error"])
        return e

    _log("ok", extra={"job_id": id})
    return {"job": job}

def list_gen_artifacts(job_id=None, artifact_type=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0012000" if __import__("os").path.isdir("./environment_mix/0012000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _record_call(endpoint, status_code, latency_ms, detail=None):
        # Best-effort request logging if a log collection exists. Do not fail the API if absent.
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                rid = "req_" + hashlib.sha256(f"{time.time_ns()}:{endpoint}".encode("utf-8")).hexdigest()[:24]
                row = {
                    "id": rid,
                    "endpoint": endpoint,
                    "status": status_code,
                    "latency_ms": int(latency_ms),
                    "timestamp": _now_iso(),
                }
                if detail is not None:
                    row["detail"] = detail
                logs.append(row)
                _save(fname, logs)
                break

    t0 = time.time()

    # Validate inputs
    if job_id is not None and not isinstance(job_id, str):
        out = _err("VALIDATION_ERROR", "job_id must be a string")
        _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
        return out

    allowed_types = {"image", "mask", "thumbnail", "metadata", "log"}
    if artifact_type is not None:
        if not isinstance(artifact_type, str):
            out = _err("VALIDATION_ERROR", "artifact_type must be a string")
            _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
            return out
        if artifact_type not in allowed_types:
            out = _err("VALIDATION_ERROR", "Invalid artifact_type", allowed=sorted(allowed_types))
            _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
            return out
        # Note: schema doesn't include "log" but tool allows it; treat as valid filter returning none if absent.

    allowed_status = {"pending", "available", "deleted"}
    if status is not None:
        if not isinstance(status, str):
            out = _err("VALIDATION_ERROR", "status must be a string")
            _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
            return out
        if status not in allowed_status:
            out = _err("VALIDATION_ERROR", "Invalid status", allowed=sorted(allowed_status))
            _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
            return out

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        out = _err("VALIDATION_ERROR", "limit must be an integer")
        _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
        return out
    if limit < 1 or limit > 200:
        out = _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
        return out

    start_offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            out = _err("VALIDATION_ERROR", "cursor must be a string")
            _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
            return out
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("bad cursor")
            start_offset = int(raw.split(":", 1)[1])
            if start_offset < 0:
                raise ValueError("bad offset")
        except Exception:
            out = _err("VALIDATION_ERROR", "Invalid cursor")
            _record_call("list_gen_artifacts", "error", (time.time() - t0) * 1000, out["error"])
            return out

    artifacts = _load("gen_artifacts.json")

    # Filter
    def _match(a):
        if not isinstance(a, dict):
            return False
        if job_id is not None and a.get("job_id") != job_id:
            return False
        if artifact_type is not None and a.get("artifact_type") != artifact_type:
            return False
        if status is not None and a.get("status") != status:
            return False
        return True

    filtered = [a for a in artifacts if _match(a)]

    # Sort: deterministic by created_at then id (fallback)
    def _sort_key(a):
        dt = _parse_iso(a.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, str(a.get("id", "")))

    filtered.sort(key=_sort_key)

    total = len(filtered)
    page = filtered[start_offset:start_offset + limit]
    next_offset = start_offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

    _record_call("list_gen_artifacts", "ok", (time.time() - t0) * 1000, {"returned": len(page), "total": total})
    return resp

def get_gen_artifact(id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0012000" if __import__("os").path.isdir("./environment_mix/0012000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_gen_artifact"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(ok, error_obj=None, extra=None):
        fname = None
        for candidate in ("api_requests.json", "request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, candidate)):
                fname = candidate
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": "ok" if ok else "error",
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_obj:
            row["error"] = error_obj
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    if id is None or not isinstance(id, str) or not id.strip():
        e = _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
        _log(False, e["error"])
        return e

    artifacts = _load("gen_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    found = None
    for a in artifacts:
        if isinstance(a, dict) and a.get("id") == id:
            found = a
            break

    # Relaxed visibility: if not found by artifact id, also allow callers who accidentally provide a job_id
    # (audit showed a job_id was passed into this endpoint). If exactly one artifact exists for that job, return it.
    # If multiple exist, return the first by deterministic ordering: sequence_index asc, artifact_type asc, id asc.
    if found is None:
        candidates = []
        for a in artifacts:
            if isinstance(a, dict) and a.get("job_id") == id:
                candidates.append(a)
        if candidates:
            def _key(a):
                si = a.get("sequence_index")
                try:
                    si = int(si)
                except Exception:
                    si = 10**9
                at = a.get("artifact_type") or ""
                aid = a.get("id") or ""
                return (si, at, aid)
            candidates.sort(key=_key)
            found = candidates[0]

    if found is None:
        e = _err("NOT_FOUND", "Artifact not found", id=id)
        _log(False, e["error"])
        return e

    resp = {"data": found}
    _log(True, extra={"id": id, "artifact_id": found.get("id"), "job_id": found.get("job_id"), "artifact_type": found.get("artifact_type")})
    return resp
